using System;using System.Linq;using NUnit.Framework;using CashflowChains.Domain;using LocalGame.Data;
public class ProductionExpansionTests {
 [Test] public void Legacy72CityProgressMigratesWithoutLosingAnything(){var p=new Profile{Stars=new int[72],Best=new long[72]};p.Stars[0]=3;p.Best[0]=1120;p.Credits=650;Profile.Validate(p);Assert.AreEqual(104,p.Stars.Length);Assert.AreEqual(3,p.Stars[0]);Assert.AreEqual(1120,p.Best[0]);Assert.AreEqual(650,p.Credits);}
 [Test] public void EveryExpansionReferenceIsLegalConservedAndThreeStar(){var seen=new System.Collections.Generic.HashSet<string>();for(int i=72;i<104;i++){var m=Campaign.Get(i);var run=new CityRun(i,m.Solution.Copy());var r=run.Preview();Assert.True(r.Conserved(),"city "+i);Assert.Greater(r.Credits,0,"city "+i);Assert.AreEqual(3,run.Stars(r.Credits));Assert.AreEqual(r.Credits,r.Events.Sum(e=>e.Credits));foreach(var n in m.Solution.Nodes)seen.Add(n.Kind);}foreach(var piece in Pieces.All.Skip(24))Assert.That(seen,Does.Contain(piece.Id));}
 [Test] public void UnownedExpansionsNeverBlockTheFreeCampaign(){var p=new Profile();Assert.False(p.CanAccess(72));Assert.False(p.CanAccess(84));p.ApplyPurchase("cc.scenario.harbor","test-harbor");Assert.True(p.CanAccess(72));Assert.False(p.CanAccess(84));p.ApplyPurchase("cc.scenario.finance","test-finance");Assert.True(p.CanAccess(84));Assert.That(p.Credits,Is.EqualTo(350));}
 [Test] public void AllDocumentedProductsHaveExactlyOnceFulfillment(){var p=new Profile();foreach(var sku in CommerceCatalog.All){Assert.True(p.ApplyPurchase(sku.Id,"test-"+sku.Id));Assert.False(p.ApplyPurchase(sku.Id,"test-"+sku.Id));}Assert.AreEqual(1760,p.Gems);Assert.AreEqual(5,p.RerollTickets);Assert.AreEqual(850,p.Credits);Assert.AreEqual(6,p.BlueprintCapacity);p.ApplyPurchase("cc.start.01","another-starter-order");Assert.AreEqual(850,p.Credits);Profile.Validate(p);}
 [Test] public void EntitlementReconciliationKeepsUncertainOfflineOwnership(){var p=new Profile();p.ApplyPurchase("cc.skin.neon","test-neon");p.ReconcilePurchases(new string[0],false);Assert.True(p.Entitlements.Contains("cc.skin.neon"));p.ReconcilePurchases(new string[0],true);Assert.False(p.Entitlements.Contains("cc.skin.neon"));Profile.Validate(p);}
 [Test] public void ForgedPremiumBalanceAndUnknownProductsAreRejected(){Assert.Throws<ArgumentException>(()=>new Profile().ApplyPurchase("invalid.sku","test"));var p=new Profile();p.Gems=100;Assert.Throws<ArgumentException>(()=>Profile.Validate(p));}
 [Test] public void SuccessfulLayoutsRecordActualContributorsAndDiscoveries(){var p=new Profile();var m=Campaign.Get(0);new CityRun(0,m.Solution.Copy()).Activate(p,"test-collection");Assert.That(p.Collection,Does.Contain("home"));Assert.That(p.Collection,Does.Contain("cafe"));Assert.That(p.DiscoveredCombos,Does.Contain("Morning rush"));Assert.That(p.Collection,Does.Not.Contain("bank"));}
 [Test] public void UnconnectedDecorationsDoNotCreateFlowCombos(){var b=Campaign.Get(0).Solution.Copy();b.Budget=2000;b.Nodes.Add(new Node(99,"factory",0,0));b.Nodes.Add(new Node(100,"bank",0,1));var r=Resolver.Run(b);Assert.That(Campaign.Combos(b,r),Does.Not.Contain("Factory town"));Assert.That(Campaign.Combos(b,r),Does.Not.Contain("Financial district"));}
}
